--
-- Name: admin_force_delete_employee(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.admin_force_delete_employee(p_employee_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
begin
  if not is_admin() then
    raise exception 'Only admins can permanently delete an employee';
  end if;

  if not exists (select 1 from employees where id = p_employee_id and company_id = my_company_id()) then
    raise exception 'Employee not found';
  end if;

  delete from task_time_logs where employee_id = p_employee_id;
  delete from tasks where assigned_to = p_employee_id;
  delete from point_redemptions where employee_id = p_employee_id;
  delete from employee_education where employee_id = p_employee_id;
  delete from employee_work_experience where employee_id = p_employee_id;
  delete from attendance_gps_requests where employee_id = p_employee_id;
  delete from attendance_correction_requests where employee_id = p_employee_id;
  delete from leave_requests where employee_id = p_employee_id;
  delete from payroll_summaries where employee_id = p_employee_id;
  delete from attendance_logs where employee_id = p_employee_id;
  delete from shifts where employee_id = p_employee_id;
  update profiles set employee_id = null where employee_id = p_employee_id;
  delete from employees where id = p_employee_id;
end;
$$;

--
-- Name: approve_attendance_correction(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.approve_attendance_correction(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
declare
  req record;
  fields record;
  reviewer uuid := auth.uid();
begin
  select * into req from attendance_correction_requests where id = p_request_id and status = 'pending';
  if not found then
    raise exception 'Correction request not found or already reviewed';
  end if;

  select * into fields from calc_payroll_fields(req.employee_id, req.requested_check_in, req.requested_check_out, req.work_date);

  insert into payroll_summaries (
    employee_id, company_id, work_date, shift_name, check_in, check_out, total_hours,
    is_late, late_minutes, is_early_departure, early_departure_minutes,
    overtime_hours, manually_corrected, device_id, computed_at
  ) values (
    req.employee_id, req.company_id, req.work_date, fields.shift_name, req.requested_check_in, req.requested_check_out,
    fields.total_hours, fields.is_late, fields.late_minutes, fields.is_early_departure,
    fields.early_departure_minutes, fields.overtime_hours, true, req.device_id, now()
  )
  on conflict (employee_id, work_date) do update set
    shift_name = excluded.shift_name,
    check_in = excluded.check_in,
    check_out = excluded.check_out,
    total_hours = excluded.total_hours,
    is_late = excluded.is_late,
    late_minutes = excluded.late_minutes,
    is_early_departure = excluded.is_early_departure,
    early_departure_minutes = excluded.early_departure_minutes,
    overtime_hours = excluded.overtime_hours,
    manually_corrected = true,
    device_id = excluded.device_id,
    computed_at = excluded.computed_at;

  update attendance_correction_requests
  set status = 'approved', reviewed_by = reviewer, reviewed_at = now()
  where id = p_request_id;
end;
$$;

--
-- Name: approve_attendance_gps_request(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.approve_attendance_gps_request(p_request_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
declare
  req record;
  reviewer uuid := auth.uid();
begin
  if not is_admin_or_hr() then
    raise exception 'Not authorized';
  end if;

  select * into req from attendance_gps_requests
  where id = p_request_id and status = 'pending' and company_id = my_company_id();
  if not found then
    raise exception 'GPS request not found or already reviewed';
  end if;

  insert into attendance_logs (employee_id, punch_time, punch_type, method, lat, lng, accuracy_m)
  values (req.employee_id, req.punch_time, req.punch_type, 'gps', req.lat, req.lng, req.accuracy_m);

  update attendance_gps_requests
  set status = 'approved', reviewed_by = reviewer, reviewed_at = now()
  where id = p_request_id;
end;
$$;

--
-- Name: block_attendance_on_leave(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.block_attendance_on_leave() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
begin
  if exists (
    select 1 from leave_requests
    where employee_id = new.employee_id
      and status = 'approved'
      and (new.punch_time at time zone 'Asia/Kathmandu')::date between start_date and end_date
  ) then
    return null;
  end if;
  return new;
end;
$$;

--
-- Name: calc_payroll_fields(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.calc_payroll_fields(emp_id uuid, p_check_in timestamp with time zone, p_check_out timestamp with time zone) RETURNS TABLE(shift_name text, total_hours numeric, is_late boolean, late_minutes integer, is_early_departure boolean, early_departure_minutes integer, overtime_hours numeric)
    LANGUAGE plpgsql STABLE
    AS $$
declare
  shift record;
  shift_start_min integer;
  shift_end_min integer;
  shift_duration_min integer;
  in_min_of_day integer;
  out_min_of_day integer;
  total_minutes integer := 0;
  late_minutes_v integer := 0;
  early_minutes_v integer := 0;
  overtime_minutes integer := 0;
  is_late_v boolean := false;
  is_early_v boolean := false;
begin
  select * into shift from find_employee_shift(emp_id);

  shift_start_min := extract(hour from shift.start_time)::integer * 60 + extract(minute from shift.start_time)::integer;
  shift_end_min := extract(hour from shift.end_time)::integer * 60 + extract(minute from shift.end_time)::integer;
  shift_duration_min := case when shift_end_min > shift_start_min
    then shift_end_min - shift_start_min
    else (24 * 60 - shift_start_min + shift_end_min)
  end;

  if p_check_in is not null then
    in_min_of_day := extract(hour from (p_check_in at time zone 'Asia/Kathmandu'))::integer * 60
      + extract(minute from (p_check_in at time zone 'Asia/Kathmandu'))::integer;
    is_late_v := in_min_of_day > (shift_start_min + shift.grace_minutes);
    late_minutes_v := case when is_late_v then in_min_of_day - shift_start_min else 0 end;
  end if;

  if p_check_in is not null and p_check_out is not null then
    total_minutes := round(extract(epoch from (p_check_out - p_check_in)) / 60);
    out_min_of_day := extract(hour from (p_check_out at time zone 'Asia/Kathmandu'))::integer * 60
      + extract(minute from (p_check_out at time zone 'Asia/Kathmandu'))::integer;
    if out_min_of_day < shift_end_min then
      is_early_v := true;
      early_minutes_v := shift_end_min - out_min_of_day;
    end if;
    if total_minutes > shift_duration_min then
      overtime_minutes := total_minutes - shift_duration_min;
    end if;
  end if;

  return query select
    shift.shift_name,
    round((total_minutes / 60.0)::numeric, 2),
    is_late_v,
    late_minutes_v,
    is_early_v,
    early_minutes_v,
    round((overtime_minutes / 60.0)::numeric, 2);
end;
$$;

--
-- Name: calc_payroll_fields(uuid, timestamp with time zone, timestamp with time zone, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.calc_payroll_fields(emp_id uuid, p_check_in timestamp with time zone, p_check_out timestamp with time zone, p_work_date date, p_total_minutes integer DEFAULT NULL::integer) RETURNS TABLE(shift_name text, total_hours numeric, is_late boolean, late_minutes integer, is_early_departure boolean, early_departure_minutes integer, overtime_hours numeric)
    LANGUAGE plpgsql STABLE
    AS $$
declare
  shift record;
  emp_exempt boolean;
  shift_start_min integer;
  shift_end_min integer;
  shift_duration_min integer;
  in_min_of_day integer;
  out_min_of_day integer;
  total_minutes integer := 0;
  late_minutes_v integer := 0;
  early_minutes_v integer := 0;
  overtime_minutes integer := 0;
  is_late_v boolean := false;
  is_early_v boolean := false;
begin
  select coalesce(attendance_exempt, false) into emp_exempt from employees where id = emp_id;
  select * into shift from find_employee_shift_for_date(emp_id, p_work_date);

  if shift.is_week_off then
    -- Nothing scheduled: never late/early. Any worked time is entirely
    -- overtime (0 scheduled hours to exceed).
    shift_duration_min := 0;
  else
    shift_start_min := extract(hour from shift.start_time)::integer * 60 + extract(minute from shift.start_time)::integer;
    shift_end_min := extract(hour from shift.end_time)::integer * 60 + extract(minute from shift.end_time)::integer;
    shift_duration_min := case when shift_end_min > shift_start_min
      then shift_end_min - shift_start_min
      else (24 * 60 - shift_start_min + shift_end_min)
    end;

    if p_check_in is not null and not emp_exempt then
      in_min_of_day := extract(hour from (p_check_in at time zone 'Asia/Kathmandu'))::integer * 60
        + extract(minute from (p_check_in at time zone 'Asia/Kathmandu'))::integer;
      is_late_v := in_min_of_day > (shift_start_min + shift.grace_minutes);
      late_minutes_v := case when is_late_v then in_min_of_day - shift_start_min else 0 end;
    end if;
  end if;

  if p_check_in is not null and p_check_out is not null then
    -- p_total_minutes (compute_payroll_summaries' pair-summed total, when it
    -- could compute one) wins over the plain span whenever it's given -- a
    -- break between two punch pairs is excluded there. NULL (a manual
    -- correction's single in/out, or a day pairing couldn't make sense of)
    -- falls back to the plain span, exactly as before.
    total_minutes := coalesce(p_total_minutes, round(extract(epoch from (p_check_out - p_check_in)) / 60));
    if not shift.is_week_off and not emp_exempt then
      out_min_of_day := extract(hour from (p_check_out at time zone 'Asia/Kathmandu'))::integer * 60
        + extract(minute from (p_check_out at time zone 'Asia/Kathmandu'))::integer;
      if out_min_of_day < shift_end_min then
        is_early_v := true;
        early_minutes_v := shift_end_min - out_min_of_day;
      end if;
    end if;
    if total_minutes > shift_duration_min then
      overtime_minutes := total_minutes - shift_duration_min;
    end if;
  end if;

  return query select
    shift.shift_name,
    round((total_minutes / 60.0)::numeric, 2),
    is_late_v,
    late_minutes_v,
    is_early_v,
    early_minutes_v,
    round((overtime_minutes / 60.0)::numeric, 2);
end;
$$;

--
-- Name: compute_payroll_summaries(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.compute_payroll_summaries(p_work_date date DEFAULT NULL::date) RETURNS integer
    LANGUAGE plpgsql
    AS $$
declare
  target_date date := coalesce(p_work_date, (now() at time zone 'Asia/Kathmandu')::date - 1);
  emp record;
  v_first_in timestamptz;
  v_last_out timestamptz;
  v_first_any timestamptz;
  v_last_any timestamptz;
  v_punch_count integer;
  v_times timestamptz[];
  v_types text[];
  v_total_minutes integer;
  check_in timestamptz;
  check_out timestamptz;
  fields record;
  rows_written integer := 0;
  v_window record;
  v_prev_window record;
  v_prev_tail timestamptz;
  v_tail timestamptz;
  d_scan date;
  d_main date;
begin
  -- Clear stale no-check-in rows for the dates this run touches. Columns are
  -- qualified because check_in is also a local variable here.
  delete from payroll_summaries
  where payroll_summaries.work_date in (target_date, target_date - 1)
    and payroll_summaries.check_in is null
    and not payroll_summaries.manually_corrected;

  -- Yesterday first, then today: see the header on why yesterday is redone.
  foreach d_main in array array[target_date - 1, target_date]
  loop
    for emp in
      select distinct e.id, e.company_id
      from employees e
      join attendance_logs al on al.employee_id = e.id
      where e.status = 'active' and (al.punch_time at time zone 'Asia/Kathmandu')::date = d_main
    loop
      select * into v_window from shift_window_for_date(emp.id, d_main);
      -- The previous day's own window, overnight or not -- needed either way
      -- now, so it's computed once here instead of only in the else branch.
      select * into v_prev_window from shift_window_for_date(emp.id, d_main - 1);
      -- The previous day's Week Off duty check-out, if it took one of today's
      -- punches. Left out of both branches below.
      v_prev_tail := week_off_duty_checkout(emp.id, d_main - 1);
      -- Reset each iteration -- only ever set below when this day's own
      -- Week Off duty tail-rescue actually fires.
      v_tail := null;

      if v_window.is_overnight then
        select
          min(punch_time) filter (where punch_type = '0'),
          max(punch_time) filter (where punch_type = '1'),
          min(punch_time) filter (where punch_type not in ('2', '3')),
          max(punch_time) filter (where punch_type not in ('2', '3')),
          count(*) filter (where punch_type not in ('2', '3'))
        into v_first_in, v_last_out, v_first_any, v_last_any, v_punch_count
        from attendance_logs
        where employee_id = emp.id
          and punch_time >= v_window.window_start and punch_time < v_window.window_end
          -- A punch yesterday's own overnight window already ends with is
          -- that day's check-out, not a fresh check-in for today -- without
          -- this, two consecutive overnight-duty days both claim it.
          and (not coalesce(v_prev_window.is_overnight, false) or punch_time >= v_prev_window.window_end)
          and punch_time is distinct from v_prev_tail
          and not punch_claimed_by_correction(emp.id, punch_time, d_main);

        select array_agg(punch_time order by punch_time), array_agg(punch_type order by punch_time)
        into v_times, v_types
        from attendance_logs
        where employee_id = emp.id
          and punch_time >= v_window.window_start and punch_time < v_window.window_end
          and (not coalesce(v_prev_window.is_overnight, false) or punch_time >= v_prev_window.window_end)
          and punch_time is distinct from v_prev_tail
          and not punch_claimed_by_correction(emp.id, punch_time, d_main)
          and punch_type not in ('2', '3');
      else
        -- Exclude any punch already claimed by an overnight shift from
        -- YESTERDAY (a checkout just after midnight Kathmandu would otherwise
        -- also raw-date-match today and get mislabeled as today's stray
        -- check-in).
        select
          min(punch_time) filter (where punch_type = '0'),
          max(punch_time) filter (where punch_type = '1'),
          min(punch_time) filter (where punch_type not in ('2', '3')),
          max(punch_time) filter (where punch_type not in ('2', '3')),
          count(*) filter (where punch_type not in ('2', '3'))
        into v_first_in, v_last_out, v_first_any, v_last_any, v_punch_count
        from attendance_logs
        where employee_id = emp.id and (punch_time at time zone 'Asia/Kathmandu')::date = d_main
          and (not v_prev_window.is_overnight or punch_time >= v_prev_window.window_end)
          and punch_time is distinct from v_prev_tail
          and not punch_claimed_by_correction(emp.id, punch_time, d_main);

        select array_agg(punch_time order by punch_time), array_agg(punch_type order by punch_time)
        into v_times, v_types
        from attendance_logs
        where employee_id = emp.id and (punch_time at time zone 'Asia/Kathmandu')::date = d_main
          and (not v_prev_window.is_overnight or punch_time >= v_prev_window.window_end)
          and punch_time is distinct from v_prev_tail
          and not punch_claimed_by_correction(emp.id, punch_time, d_main)
          and punch_type not in ('2', '3');
      end if;

      check_in := coalesce(v_first_in, v_first_any);
      check_out := case when v_punch_count > 1 then coalesce(v_last_out, v_last_any) else null end;
      if check_out = check_in then
        check_out := null;
      end if;

      -- Worked minutes actually earned between this window's own punches,
      -- paired up instead of spanned -- see sum_paired_minutes() (it falls
      -- back to positional pairing, then to the plain span, on its own when
      -- the punches don't carry a usable type).
      v_total_minutes := sum_paired_minutes(v_times, v_types);

      -- A Week Off duty that ran into the next morning: its check-out is the
      -- next day's first punch (week_off_duty_checkout() re-checks that this
      -- is a Week Off with a lone check-in).
      if check_in is not null and check_out is null then
        v_tail := week_off_duty_checkout(emp.id, d_main);
        if v_tail is not null then
          check_out := v_tail;
          -- That rescued punch lies outside v_times (it's from the next
          -- calendar day), so pairing can't account for it -- fall back to
          -- the plain span (check_out - check_in), exactly as before this
          -- migration.
          v_total_minutes := null;
        end if;
      end if;

      -- No usable check-in: every punch this employee had for d_main was
      -- claimed by the previous day (an overnight window or a Week Off
      -- duty). Nothing to summarize, and any row already saved for this date
      -- is stale, so it goes.
      if check_in is null then
        delete from payroll_summaries
        where payroll_summaries.employee_id = emp.id
          and payroll_summaries.work_date = d_main
          and not payroll_summaries.manually_corrected;
        continue;
      end if;

      select * into fields from calc_payroll_fields(emp.id, check_in, check_out, d_main, v_total_minutes);

      insert into payroll_summaries (
        employee_id, company_id, work_date, shift_name, check_in, check_out, total_hours,
        is_late, late_minutes, is_early_departure, early_departure_minutes,
        overtime_hours, computed_at
      ) values (
        emp.id, emp.company_id, d_main, fields.shift_name, check_in, check_out, fields.total_hours,
        fields.is_late, fields.late_minutes, fields.is_early_departure, fields.early_departure_minutes,
        fields.overtime_hours, now()
      )
      on conflict (employee_id, work_date) do update set
        shift_name = excluded.shift_name,
        check_in = excluded.check_in,
        check_out = excluded.check_out,
        total_hours = excluded.total_hours,
        is_late = excluded.is_late,
        late_minutes = excluded.late_minutes,
        is_early_departure = excluded.is_early_departure,
        early_departure_minutes = excluded.early_departure_minutes,
        overtime_hours = excluded.overtime_hours,
        computed_at = excluded.computed_at
      where payroll_summaries.manually_corrected = false;

      rows_written := rows_written + 1;
    end loop;
  end loop;

  -- SECOND PASS: overnight duty dates whose only punch is the next-morning
  -- tap-out. Scans target_date and the day before. Not affected by the
  -- earlier fix in this loop: this only ever runs for a date with ZERO
  -- raw-dated punches of its own, so a punch it finds can only be dated the
  -- day after, never a leftover from the day before. No Week Off duty tail
  -- concept here either (this IS the rescue for that scenario's own date).
  foreach d_scan in array array[target_date, target_date - 1]
  loop
    for emp in
      select e.id, e.company_id
      from employees e
      where e.status = 'active'
        and not exists (
          select 1 from attendance_logs al
          where al.employee_id = e.id
            and (al.punch_time at time zone 'Asia/Kathmandu')::date = d_scan
        )
    loop
      select * into v_window from shift_window_for_date(emp.id, d_scan);
      if not coalesce(v_window.is_overnight, false) then
        continue;
      end if;

      select
        min(punch_time) filter (where punch_type = '0'),
        max(punch_time) filter (where punch_type = '1'),
        min(punch_time) filter (where punch_type not in ('2', '3')),
        max(punch_time) filter (where punch_type not in ('2', '3')),
        count(*) filter (where punch_type not in ('2', '3'))
      into v_first_in, v_last_out, v_first_any, v_last_any, v_punch_count
      from attendance_logs
      where employee_id = emp.id
        and punch_time >= v_window.window_start and punch_time < v_window.window_end
        and not punch_claimed_by_correction(emp.id, punch_time, d_scan);

      if coalesce(v_punch_count, 0) = 0 then
        continue;
      end if;

      -- Only rescue when the day after the duty is itself a Week Off, so a
      -- real working day never loses its own check-in to this window.
      if not (select is_week_off from find_employee_shift_for_date(emp.id, d_scan + 1)) then
        continue;
      end if;

      select array_agg(punch_time order by punch_time), array_agg(punch_type order by punch_time)
      into v_times, v_types
      from attendance_logs
      where employee_id = emp.id
        and punch_time >= v_window.window_start and punch_time < v_window.window_end
        and not punch_claimed_by_correction(emp.id, punch_time, d_scan)
        and punch_type not in ('2', '3');

      check_in := coalesce(v_first_in, v_first_any);
      check_out := case when v_punch_count > 1 then coalesce(v_last_out, v_last_any) else null end;
      if check_out = check_in then
        check_out := null;
      end if;
      if check_in is null then
        continue;
      end if;

      v_total_minutes := sum_paired_minutes(v_times, v_types);

      select * into fields from calc_payroll_fields(emp.id, check_in, check_out, d_scan, v_total_minutes);

      insert into payroll_summaries (
        employee_id, company_id, work_date, shift_name, check_in, check_out, total_hours,
        is_late, late_minutes, is_early_departure, early_departure_minutes,
        overtime_hours, computed_at
      ) values (
        emp.id, emp.company_id, d_scan, fields.shift_name, check_in, check_out, fields.total_hours,
        fields.is_late, fields.late_minutes, fields.is_early_departure, fields.early_departure_minutes,
        fields.overtime_hours, now()
      )
      on conflict (employee_id, work_date) do update set
        shift_name = excluded.shift_name,
        check_in = excluded.check_in,
        check_out = excluded.check_out,
        total_hours = excluded.total_hours,
        is_late = excluded.is_late,
        late_minutes = excluded.late_minutes,
        is_early_departure = excluded.is_early_departure,
        early_departure_minutes = excluded.early_departure_minutes,
        overtime_hours = excluded.overtime_hours,
        computed_at = excluded.computed_at
      where payroll_summaries.manually_corrected = false;

      rows_written := rows_written + 1;
    end loop;
  end loop;

  return rows_written;
end;
$$;

--
-- Name: devices; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE attendance.devices (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    branch_id uuid,
    ip_address text DEFAULT '192.168.1.201'::text NOT NULL,
    port integer DEFAULT 4370 NOT NULL,
    status text DEFAULT 'online'::text NOT NULL,
    last_sync timestamp with time zone,
    company_id uuid NOT NULL,
    serial_number text,
    CONSTRAINT devices_status_check CHECK ((status = ANY (ARRAY['online'::text, 'offline'::text])))
);

--
-- Name: devices_with_punches(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.devices_with_punches() RETURNS SETOF attendance.devices
    LANGUAGE sql STABLE
    AS $$
  select d.*
  from devices d
  where exists (select 1 from attendance_logs l where l.device_id = d.id)
  order by d.name;
$$;

--
-- Name: enforce_geofence(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.enforce_geofence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  b branches%rowtype;
  emp employees%rowtype;
begin
  if new.method = 'gps' then
    select * into emp from employees where id = new.employee_id;
    select * into b from branches where id = emp.branch_id;
    if b.id is null then
      raise exception 'Employee has no assigned branch for geofence check';
    end if;
    -- Distance is no longer checked here — no radius rejection.
  end if;

  if new.method = 'qr' then
    if not exists (
      select 1 from qr_tokens
      where id = new.qr_token_id and expires_at > now()
    ) then
      raise exception 'Punch rejected: QR token expired or invalid';
    end if;
  end if;

  return new;
end;
$$;

--
-- Name: find_employee_shift(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.find_employee_shift(emp_id uuid) RETURNS TABLE(shift_name text, start_time time without time zone, end_time time without time zone, grace_minutes integer)
    LANGUAGE plpgsql STABLE
    AS $$
declare
  emp_dept text;
  emp_company uuid;
begin
  return query
    select s.name, s.start_time, s.end_time, s.grace_minutes
    from shifts s where s.employee_id = emp_id
    order by s.id
    limit 1;
  if found then
    return;
  end if;

  select department, company_id into emp_dept, emp_company from employees where id = emp_id;

  return query
    select s.name, s.start_time, s.end_time, s.grace_minutes
    from shifts s
    where s.department is not distinct from emp_dept
      and s.employee_id is null
      and s.company_id = emp_company
    order by s.id
    limit 1;
  if found then
    return;
  end if;

  return query select 'Default'::text, '09:00'::time, '18:00'::time, 10;
end;
$$;

--
-- Name: find_employee_shift_for_date(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.find_employee_shift_for_date(emp_id uuid, p_work_date date) RETURNS TABLE(shift_name text, start_time time without time zone, end_time time without time zone, grace_minutes integer, is_week_off boolean)
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_company_id uuid;
  v_weekly_off_day integer;
  v_roster_mode text;
  v_pattern_exists boolean;
  v_pattern_shift_id uuid;
begin
  if exists (select 1 from employee_daily_shifts where employee_id = emp_id and work_date = p_work_date) then
    return query
      select s.name, s.start_time, s.end_time, s.grace_minutes, false
      from employee_daily_shifts eds
      join shifts s on s.id = eds.shift_id
      where eds.employee_id = emp_id and eds.work_date = p_work_date;
    if found then
      return;
    end if;
    return query select 'Week Off'::text, null::time, null::time, 0, true;
    return;
  end if;

  select company_id into v_company_id from employees where id = emp_id;
  if v_company_id is not null then
    select roster_mode, weekly_off_day into v_roster_mode, v_weekly_off_day
      from companies where id = v_company_id;

    if v_roster_mode = 'weekly' then
      select exists(
        select 1 from employee_weekly_pattern
        where employee_id = emp_id and weekday = extract(dow from p_work_date)
      ) into v_pattern_exists;

      if v_pattern_exists then
        select shift_id into v_pattern_shift_id from employee_weekly_pattern
          where employee_id = emp_id and weekday = extract(dow from p_work_date);
        if v_pattern_shift_id is null then
          return query select 'Week Off'::text, null::time, null::time, 0, true;
          return;
        end if;
        return query
          select s.name, s.start_time, s.end_time, s.grace_minutes, false
          from shifts s where s.id = v_pattern_shift_id;
        if found then
          return;
        end if;
      end if;
    end if;

    if v_weekly_off_day is not null and extract(dow from p_work_date) = v_weekly_off_day then
      return query select 'Week Off'::text, null::time, null::time, 0, true;
      return;
    end if;
    if exists (select 1 from company_holidays where company_id = v_company_id and holiday_date = p_work_date) then
      return query select 'Week Off'::text, null::time, null::time, 0, true;
      return;
    end if;
  end if;

  return query
    select f.shift_name, f.start_time, f.end_time, f.grace_minutes, false
    from find_employee_shift(emp_id) f;
end;
$$;

--
-- Name: get_leaderboard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.get_leaderboard() RETURNS TABLE(employee_id uuid, name text, department text, total_points bigint, tasks_completed bigint, profile_photo_url text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  return query
    select
      e.id,
      e.name,
      e.department,
      coalesce(sum(t.points) filter (where t.status = 'approved'), 0)::bigint
        - coalesce((select sum(pr.points_requested) from point_redemptions pr where pr.employee_id = e.id and pr.status = 'approved'), 0)::bigint,
      count(*) filter (where t.status = 'approved')::bigint,
      e.profile_photo_url
    from employees e
    left join tasks t on t.assigned_to = e.id
    where e.status = 'active' and e.company_id = my_company_id()
    group by e.id, e.name, e.department, e.profile_photo_url
    order by 4 desc, e.name asc;
end;
$$;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
declare
  v_company_id uuid;
  v_role text := 'employee';
  v_full_name text := new.raw_user_meta_data ->> 'full_name';
  v_company_name text := new.raw_user_meta_data ->> 'company_name';
  v_location text := new.raw_user_meta_data ->> 'location';
begin
  if new.raw_user_meta_data ->> 'company_id' is not null then
    v_company_id := (new.raw_user_meta_data ->> 'company_id')::uuid;
  elsif v_company_name is not null and trim(v_company_name) <> '' then
    insert into attendance.companies (name, created_by) values (trim(v_company_name), new.id)
    returning id into v_company_id;
    v_role := 'admin';
  end if;

  insert into attendance.profiles (id, role, full_name, company_name, company_id, location)
  values (new.id, v_role, v_full_name, v_company_name, v_company_id, v_location)
  on conflict (id) do nothing;
  return new;
end;
$$;

