-- Name: my_company_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.my_company_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
