$$;

--
-- Name: punch_claimed_by_correction(uuid, timestamp with time zone, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.punch_claimed_by_correction(p_employee_id uuid, p_punch timestamp with time zone, p_date date) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select exists (
    select 1 from payroll_summaries ps
    where ps.employee_id = p_employee_id
      and ps.manually_corrected
      and ps.work_date <> p_date
      and ps.check_in is not null
      and p_punch >= date_trunc('minute', ps.check_in)
      and p_punch < date_trunc('minute', coalesce(ps.check_out, ps.check_in)) + interval '1 minute'
  );
$$;

--
-- Name: queue_device_userinfo_sync(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.queue_device_userinfo_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
declare
  cmd text;
begin
  if new.fingerprint_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.name = new.name and old.fingerprint_id is not distinct from new.fingerprint_id then
    return new;
  end if;

  -- Plain ADMS "DATA UPDATE USERINFO" command — Pri=0 (normal user, not
  -- admin), Verify=0 (any verification method), no card/password managed
  -- here. Tabs are the field separator the protocol expects; strip any
  -- (implausible) tab out of the name so it can't smuggle an extra field in.
  cmd := 'DATA UPDATE USERINFO PIN=' || new.fingerprint_id
    || E'\tName=' || replace(new.name, E'\t', ' ')
    || E'\tPri=0\tPasswd=\tCard=\tGrp=1\tTZ=0000000000000000\tVerify=0';

  insert into device_command_queue (device_id, command)
  select d.id, cmd from devices d where d.company_id = new.company_id;

  return new;
end;
$$;

--
-- Name: shift_window_for_date(uuid, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.shift_window_for_date(emp_id uuid, p_work_date date) RETURNS TABLE(is_overnight boolean, window_start timestamp with time zone, window_end timestamp with time zone)
    LANGUAGE plpgsql STABLE
    AS $$
declare
  shift record;
  start_min integer;
  end_min integer;
  duration_min integer;
begin
  select * into shift from find_employee_shift_for_date(emp_id, p_work_date);
  if shift.is_week_off or shift.start_time is null or shift.end_time is null then
    return query select false, null::timestamptz, null::timestamptz;
    return;
  end if;

  start_min := extract(hour from shift.start_time)::integer * 60 + extract(minute from shift.start_time)::integer;
  end_min := extract(hour from shift.end_time)::integer * 60 + extract(minute from shift.end_time)::integer;

  if end_min > start_min then
    return query select false, null::timestamptz, null::timestamptz;
    return;
  end if;

  duration_min := 24 * 60 - start_min + end_min;
  return query select
    true,
    (p_work_date::text || ' 00:00:00')::timestamp at time zone 'Asia/Kathmandu',
    (p_work_date::text || ' ' || shift.start_time::text)::timestamp at time zone 'Asia/Kathmandu'
      + (duration_min + 120) * interval '1 minute';
end;
$$;

--
-- Name: stamp_company_id_from_assignee(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.stamp_company_id_from_assignee() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
begin
  new.company_id := (select company_id from employees where id = new.assigned_to);
  if new.company_id is null then
    raise exception 'No such employee, or employee has no company_id';
  end if;
  return new;
end;
$$;

