  end if;
  return new;
end;
$$;

--
-- Name: stamp_company_id_from_branch_or_self(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.stamp_company_id_from_branch_or_self() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
begin
  if new.branch_id is not null then
    new.company_id := (select company_id from branches where id = new.branch_id);
    if new.company_id is null then
      raise exception 'No such branch, or branch has no company_id';
    end if;
  else
    new.company_id := my_company_id();
    if new.company_id is null then
      raise exception 'company_id could not be determined for this insert';
    end if;
  end if;
  return new;
end;
$$;

