--
-- Name: start_task(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.start_task(p_task_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  emp_id uuid;
begin
  select employee_id into emp_id from profiles where id = auth.uid();
  update tasks set status = 'in_progress'
  where id = p_task_id and assigned_to = emp_id and status = 'pending';
  if not found then
    raise exception 'Task not found or not eligible to start';
  end if;
end;
$$;

--
-- Name: start_task_timer(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.start_task_timer(p_task_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  emp_id uuid;
  task_status text;
  new_log_id uuid;
begin
  select employee_id into emp_id from profiles where id = auth.uid();
  if emp_id is null then
    raise exception 'No employee linked to this account';
  end if;

  select status into task_status from tasks where id = p_task_id and assigned_to = emp_id;
  if task_status is null then
    raise exception 'Task not found';
  end if;
  if task_status not in ('pending', 'in_progress') then
    raise exception 'This task is no longer active';
  end if;

  if exists (select 1 from task_time_logs where employee_id = emp_id and ended_at is null) then
    raise exception 'Stop your currently running timer before starting another task';
  end if;

  if task_status = 'pending' then
    update tasks set status = 'in_progress' where id = p_task_id;
  end if;

  insert into task_time_logs (task_id, employee_id, started_at)
  values (p_task_id, emp_id, now())
  returning id into new_log_id;

  return new_log_id;
end;
$$;

--
-- Name: stop_task_timer(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.stop_task_timer(p_log_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  emp_id uuid;
begin
  select employee_id into emp_id from profiles where id = auth.uid();
  update task_time_logs set ended_at = now()
  where id = p_log_id and employee_id = emp_id and ended_at is null;
  if not found then
    raise exception 'Timer not found or already stopped';
  end if;
end;
$$;

--
-- Name: submit_task(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.submit_task(p_task_id uuid, p_work_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  emp_id uuid;
begin
  select employee_id into emp_id from profiles where id = auth.uid();
  update tasks set status = 'submitted', work_notes = p_work_notes, submitted_at = now()
  where id = p_task_id and assigned_to = emp_id and status in ('pending', 'in_progress');
  if not found then
    raise exception 'Task not found or not eligible to submit';
  end if;

  update task_time_logs set ended_at = now()
  where task_id = p_task_id and employee_id = emp_id and ended_at is null;
end;
$$;

--
-- Name: sum_paired_minutes(timestamp with time zone[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.sum_paired_minutes(p_times timestamp with time zone[], p_types text[]) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
declare
  i integer;
  n integer;
  open_in timestamptz;
  total numeric := 0;
begin
  if p_times is null then
    return 0;
  end if;
  n := array_length(p_times, 1);

  if '1' = any(p_types) then
    -- A '0' with no open pair starts one; a '1' closes whatever's open and
    -- is otherwise ignored -- an unmatched extra check-in (forgot to punch
    -- out, then punched in again) simply never closes, rather than being
    -- paired with whatever comes next regardless of its type.
    for i in 1 .. n loop
      if p_types[i] = '0' then
        if open_in is null then
          open_in := p_times[i];
        end if;
      elsif p_types[i] = '1' and open_in is not null then
        total := total + extract(epoch from (p_times[i] - open_in)) / 60;
        open_in := null;
      end if;
    end loop;
    return round(total)::integer;
  end if;

  -- No usable type signal at all -- chronological position is all that's
  -- left. See this migration's header for the even/odd reasoning.
  if n % 2 <> 0 then
    return round(extract(epoch from (p_times[n] - p_times[1])) / 60)::integer;
  end if;
  for i in 1 .. n by 2 loop
    total := total + extract(epoch from (p_times[i + 1] - p_times[i])) / 60;
  end loop;
  return round(total)::integer;
end;
$$;

--
-- Name: superadmin_delete_company(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.superadmin_delete_company(target_company_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'attendance'
    AS $$
begin
  -- Level 0: leaf tables — nothing else references these, safe to delete
  -- first regardless of order among themselves. reviewed_by/assigned_by/
  -- created_by/requested_by pointers at profiles(id) are already
  -- on-delete-set-null (see 20260817180000_nullify_deleted_user_references)
  -- so deleting profiles later in this same function never blocks on them.
  delete from attendance_correction_requests where company_id = target_company_id;
  delete from attendance_gps_requests where company_id = target_company_id;
  delete from leave_requests where company_id = target_company_id;
  delete from payroll_summaries where company_id = target_company_id;
  delete from point_redemptions where company_id = target_company_id;
  delete from push_tokens where company_id = target_company_id;
  delete from employee_education where company_id = target_company_id;
  delete from employee_work_experience where company_id = target_company_id;
  delete from employee_daily_shifts where company_id = target_company_id;
  delete from employee_weekly_pattern where company_id = target_company_id;
  delete from device_sync_events where company_id = target_company_id;
  delete from device_command_queue where company_id = target_company_id;
  delete from task_time_logs where company_id = target_company_id;
  delete from attendance_logs where company_id = target_company_id;
  delete from company_holidays where company_id = target_company_id;

  -- Level 1: referenced by level 0 (tasks by task_time_logs, shifts by
  -- employee_daily_shifts/employee_weekly_pattern, qr_tokens by
  -- attendance_logs, devices by attendance_logs/device_sync_events/
  -- device_command_queue) — all now clear of level-0 rows.
  delete from tasks where company_id = target_company_id;
  delete from shifts where company_id = target_company_id;
  delete from qr_tokens where company_id = target_company_id;
  delete from devices where company_id = target_company_id;

  -- profiles.employee_id -> employees(id) with no on-delete clause means
  -- employees can't be deleted while a profile still points at one — so
  -- profiles has to go before employees, not after (and not via deleting
  -- auth.users — see the file header for why this deletes profiles
  -- directly instead).
  delete from profiles where company_id = target_company_id;

  -- Level 2: employees (now unreferenced by shifts/tasks/profiles/every
  -- level-0 table above) and branch_departments (branch_id/department_id
  -- both already on-delete-cascade from branches/departments, but deleted
  -- explicitly here too rather than relying on that).
  delete from employees where company_id = target_company_id;
  delete from branch_departments where company_id = target_company_id;

  -- Level 3: departments and branches — now unreferenced by employees,
  -- devices, qr_tokens, or branch_departments.
  delete from departments where company_id = target_company_id;
  delete from branches where company_id = target_company_id;

  -- Finally the company row itself.
  delete from companies where id = target_company_id;
end;
$$;

--
-- Name: update_my_profile(text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.update_my_profile(p_name text, p_email text, p_phone text, p_address text, p_department text, p_designation text, p_photo_url text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  emp_id uuid;
begin
  select employee_id into emp_id from profiles where id = auth.uid();
  if emp_id is null then
    raise exception 'No employee linked to this account';
  end if;

  update employees
  set name = p_name,
      email = p_email,
      phone = p_phone,
      address = p_address,
      department = p_department,
      designation = p_designation,
      profile_photo_url = p_photo_url
  where id = emp_id;
end;
$$;

--
-- Name: update_my_profile(text, text, text, text, text, text, text, text[], text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.update_my_profile(p_name text, p_email text, p_phone text, p_address text, p_department text, p_designation text, p_photo_url text, p_skills text[], p_emergency_contact_name text, p_emergency_contact_relationship text, p_emergency_contact_phone text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  emp_id uuid;
begin
  select employee_id into emp_id from profiles where id = auth.uid();
  if emp_id is null then
    raise exception 'No employee linked to this account';
  end if;

  update employees
  set name = p_name,
      email = p_email,
      phone = p_phone,
      address = p_address,
      department = p_department,
      designation = p_designation,
      profile_photo_url = p_photo_url,
      skills = coalesce(p_skills, '{}'),
      emergency_contact_name = p_emergency_contact_name,
      emergency_contact_relationship = p_emergency_contact_relationship,
      emergency_contact_phone = p_emergency_contact_phone
  where id = emp_id;
end;
$$;

--
-- Name: week_off_duty_checkout(uuid, date, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION attendance.week_off_duty_checkout(p_employee_id uuid, p_date date, p_depth integer DEFAULT 0) RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    AS $$
declare
  v_prev_window record;
  v_prev_tail timestamptz;
  v_count integer;
  v_in timestamptz;
  v_out timestamptz;
begin
  -- A run of lone punches on consecutive Week Offs is rare; a week is plenty.
  if p_depth > 7 then
    return null;
  end if;

  if not exists (
    select 1 from employees e
    join companies c on c.id = e.company_id
    where e.id = p_employee_id and c.week_off_work_earns_leave
  ) then
    return null;
  end if;

  if not coalesce((select is_week_off from find_employee_shift_for_date(p_employee_id, p_date)), false) then
    return null;
  end if;

  -- A day the admin corrected or deleted is settled: it takes no punch from
  -- the next morning.
  if exists (
    select 1 from payroll_summaries
    where employee_id = p_employee_id and work_date = p_date and manually_corrected
  ) then
    return null;
  end if;

  select * into v_prev_window from shift_window_for_date(p_employee_id, p_date - 1);
  v_prev_tail := week_off_duty_checkout(p_employee_id, p_date - 1, p_depth + 1);

  -- This Week Off's own punches: its calendar date, minus anything the day
  -- before already claimed (an overnight shift's window, or a Week Off duty's
  -- check-out). Exactly one = a check-in with no check-out.
  select count(*), min(punch_time) into v_count, v_in
  from attendance_logs
  where employee_id = p_employee_id
    and punch_type not in ('2', '3')
    and (punch_time at time zone 'Asia/Kathmandu')::date = p_date
    and (not coalesce(v_prev_window.is_overnight, false) or punch_time >= v_prev_window.window_end)
    and punch_time is distinct from v_prev_tail
    and not punch_claimed_by_correction(p_employee_id, punch_time, p_date);

  if v_count <> 1 then
    return null;
  end if;

  select min(punch_time) into v_out
  from attendance_logs
  where employee_id = p_employee_id
    and punch_type not in ('2', '3')
    and (punch_time at time zone 'Asia/Kathmandu')::date = p_date + 1
    and punch_time > v_in
    and punch_time <= v_in + interval '26 hours'
    and not punch_claimed_by_correction(p_employee_id, punch_time, p_date + 1);

  if v_out is null then
    return null;
  end if;

  -- A next day that is a working day with punches of its own (e.g. an 8h day
  -- shift, check-in and check-out) keeps its first punch: that is its own
  -- check-in, not this Week Off's check-out.
  if not coalesce((select is_week_off from find_employee_shift_for_date(p_employee_id, p_date + 1)), false)
     and (
       select count(*) from attendance_logs
       where employee_id = p_employee_id
         and punch_type not in ('2', '3')
         and (punch_time at time zone 'Asia/Kathmandu')::date = p_date + 1
         and not punch_claimed_by_correction(p_employee_id, punch_time, p_date + 1)
     ) > 1 then
    return null;
  end if;

  return v_out;
end;
$$;

