CREATE VIEW attendance.employees_on_leave_today WITH (security_invoker='on') AS
 SELECT employee_id
   FROM attendance.leave_requests
  WHERE ((status = 'approved'::text) AND ((CURRENT_DATE >= start_date) AND (CURRENT_DATE <= end_date)));

